pub fn admit(
    ws_670: Rc<List<Wt>>,
    c_671: Cls,
    cap_672: u64,
    now_673: u64,
    hs_674: Rc<List<Hd>>,
    m_675: u64,
    fx_676: Rc<List<Fx>>,
    adm_677: bool,
    room_678: bool,
) -> Adm {
    match &*ws_670 {
        List::Nil => {
            return Adm::Adm(hs_674.clone(), m_675, Rc::new(List::Nil), fx_676.clone());
        }
        List::Con(h__, t__) => {
            let head_762: Wt = h__.clone();
            let tail_763: Rc<List<Wt>> = t__.clone();
            match &head_762 {
                Wt::Wt(f0__, f1__, f2__) => {
                    let ticket_767: u64 = f0__.clone();
                    let cls_768: Cls = f1__.clone();
                    let share_769: Shr = f2__.clone();
                    if adm_677 {
                        if room_678 {
                            return admit(
                                tail_763.clone(),
                                c_671.clone(),
                                cap_672,
                                now_673,
                                Rc::new(List::Con(
                                    Hd::Hd(ticket_767, cls_768.clone(), share_769.clone(), now_673),
                                    hs_674.clone(),
                                )),
                                nat_add(m_675, 1u64),
                                snoc_f(fx_676.clone(), Fx::FxGrant(ticket_767)),
                                head_adm(c_671.clone(), tail_763.clone()),
                                head_room(
                                    Rc::new(List::Con(
                                        Hd::Hd(
                                            ticket_767,
                                            cls_768.clone(),
                                            share_769.clone(),
                                            now_673,
                                        ),
                                        hs_674.clone(),
                                    )),
                                    tail_763.clone(),
                                    cap_672,
                                ),
                            );
                        } else {
                            return Adm::Adm(
                                hs_674.clone(),
                                m_675,
                                Rc::new(List::Con(
                                    Wt::Wt(ticket_767, cls_768.clone(), share_769.clone()),
                                    tail_763.clone(),
                                )),
                                fx_676.clone(),
                            );
                        }
                    } else {
                        return admit_skip(
                            Wt::Wt(ticket_767, cls_768.clone(), share_769.clone()),
                            admit(
                                tail_763.clone(),
                                c_671.clone(),
                                cap_672,
                                now_673,
                                hs_674.clone(),
                                m_675,
                                fx_676.clone(),
                                head_adm(c_671.clone(), tail_763.clone()),
                                head_room(hs_674.clone(), tail_763.clone(), cap_672),
                            ),
                        );
                    }
                }
            }
        }
    }
}

