pub fn same(a_314: u64, b_315: u64) -> bool {
    if a_314 == 0 {
        if b_315 == 0 {
            return true;
        } else {
            let pred_723: u64 = b_315 - 1;
            return false;
        }
    } else {
        let pred_725: u64 = a_314 - 1;
        if b_315 == 0 {
            return false;
        } else {
            let pred_727: u64 = b_315 - 1;
            return same(pred_725, pred_727);
        }
    }
}

